### 1.4.3 bind

bind是 function 的一个函数扩展方法，bind 以后代码重新绑定了func内部的 this 指向,不会调用方法,不兼容 IE8

```js
  var name = '李四'
  var foo = {
    name: "张三",
    logName: function(age) {
    console.log(this.name, age);
    }
  }
  var fooNew = foo.logName;
  var fooNewBind = foo.logName.bind(foo);
  fooNew(10)//李四,10
  fooNewBind(11)//张三,11  因为bind改变了fooNewBind里面的this指向
```

### 1.4.4 call,apply和bind原生实现

call实现:

```js
  Function.prototype.newCall = function(context, ...parameter) {
  if (typeof context === 'object' || typeof context === 'function') {
      context = context || window
  } else {
      context = Object.create(null)
  }
    context[fn] = this  
    const res =context[fn](...parameter)
    delete context.fn;
    return res
  }
  let person = {
    name: 'Abiel'
  }
  function sayHi(age,sex) {
    console.log(this.name, age, sex);
  }
  sayHi.newCall (person, 25, '男'); // Abiel 25 男
```

apply实现:

```js
  Function.prototype.newApply = function(context, parameter) {
    if (typeof context === 'object' || typeof context === 'function') {
      context = context || window
    } else {
      context = Object.create(null)
    }
    let fn = Symbol()
    context[fn] = this
    return res=context[fn](..parameter);
    delete context[fn]
    return res
  }
  sayHi.newApply (person,[ 25, '男']) //Abiel 25 男
```

bind实现:

```js
  Function.prototype.bind = function (context,...innerArgs) {
    var me = this
    return function (...finnalyArgs) {
      return me.call(context,...innerArgs,...finnalyArgs)
    }
  }
  let person = {
    name: 'Abiel'
  }
  function sayHi(age,sex) {
    console.log(this.name, age, sex);
  }
  let personSayHi = sayHi.bind(person, 25)
  personSayHi('男')
```

### 1.4.5 三者异同

同:都是改变 this 指向,都可接收参数

异: bind 和 call 是接收单个参数, apply 是接收数组

## 1.5.函数的节流和防抖

| 类型 | 概念                                      | 应用                                  |
| ---- | ----------------------------------------- | ------------------------------------- |
| 节流 | 事件触发后每隔一段时间触发一次,可触发多次 | scroll,resize事件一段时间触发多次     |
| 防抖 | 事件触发动作完成后一段时间触发一次        | scroll,resize事件触发完后一段时间触发 |

节流:

### 1.5.1 节流

```js
  let throttle = function(func, delay) {
      let timer = null;
      return ()=> {
        if (!timer) {
          timer = setTimeout(function() {
            func.apply(this, arguments);
            timer = null;
          }, delay);
        }
      };
    };
    function handle() {
      console.log(Math.random());
    }
    window.addEventListener("scroll", throttle(handle, 1000)); //事件处理函数
```

### 1.5.2 防抖

```js
  function debounce(fn, wait) {
      var timeout = null;
      return function() {
        if (timeout !== null) clearTimeout(timeout);//如果多次触发将上次记录延迟清除掉
        timeout = setTimeout(()=> {
            fn.apply(this, arguments);
            timeout = null;
          }, wait);
      };
    }
    // 处理函数
    function handle() {
      console.log(Math.random());
    }
    // 滚动事件
    window.addEventListener("scroll", debounce(handle, 1000));
```

