      }

  render() {
    return <Child parms={this.state.msg} />;
  }
}



class Child extends Component{

     constructor(props) {
        super(props);
        // call parent component
        console.log("parms :",this.props.parms);
       this.props.transMsg("hi ~~");
    }

  render() {
    return <p>{this.props.parms}</p>
  }
}

