## 在mpvue中封装http发送请求

```js
// 返回promise对象
function request(url, method="GET", data={}, header={}){

    wx.showLoading({
        title: '加载中',
    })

    return new Promise((resolve, reject) => {
        wx.request({
            url,
            method,
            data,
            header,
            success: res => {
                resolve(res);
                wx.hideLoading();
            }
        })
    });
}

// 拓展get请求
request.get = function(url, data){
    // 返回promise
    return request(url, "GET", data);
}

// 拓展Post请求
request.post = function(url, data){
    // 返回promise
    return request(url, "POST", data);
}

// 需要授权访问的请求
request.auth = function(url, data){

    // 从本地获取token
    if(!wx.getStorageSync("token")){
        wx.navigateTo({
            url: "/pages/auth/main"
        });
        return new Promise(() => {});
    }

    // 返回promise
    // 注意，第四个参数是header头信息
    return request(url, "POST", data, {
        "Authorization" : wx.getStorageSync("token")
    });
}

export default request;

```

## 在mpvue使用封装好的请求，在使用async和await处理异步请求

```js
  methods: {
    // 负责请求页面全部的数据
    async getData(){
      // try catch捕获程序代码的错误，代码块错误不会影响到下面的代码执行,具有块级作用域
      try {
        const res = await request("https://xxxx"); //此网址为你的api请求
        const {data} = res.data;

        // 修改轮播图的连接
        data.forEach(v => {
          // 通过问号分解链接，给第一个元素后面加上/mian，再通过join拼接为字符串
          const arr = v.navigator_url.split("?");
          arr[0] = arr[0] + "/main";
          const str = arr.join("?")
          v.navigator_url = str;
        })

        this.imgUrls = data;
      } catch (error) { console.log(error) }

      try {
        const res = await request("https://xxx"); // 此网址为你的api请求
        const {data} = res.data;
        this.categorys = data;
      } catch (error) { console.log(error) }

      try {
        const res = await request("https://bbb"); // 此网址为你的api请求
        const {message} = res.data;
        this.floors = message;
      } catch (error) { console.log(error) }

      // 停止下拉刷新
      wx.stopPullDownRefresh();
    },

    // 回到顶部
